package main

import (
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(num())
	a := make([]int64, n)
	for i := range a {
		a[i] = num()
	}
	var target, totals, counts [3]int64
	for g := range target {
		target[g] = num()
	}
	shift := num()
	answer := int64(math.MaxInt64)
	abs := func(x int64) int64 {
		if x < 0 {
			return -x
		}
		return x
	}
	// Assign region i to target group 0/1/2 or leave it unused.
	var search func(i int)
	search = func(i int) {
		empty := 0
		for _, c := range counts {
			if c == 0 {
				empty++
			}
		}
		if empty > n-i { // not enough regions left to fill every group
			return
		}
		if i == n {
			var cost int64
			for g := 0; g < 3; g++ {
				cost += (counts[g]-1)*shift + abs(totals[g]-target[g])
			}
			answer = min(answer, cost)
			return
		}
		search(i + 1)
		for g := 0; g < 3; g++ {
			totals[g] += a[i]
			counts[g]++
			search(i + 1)
			totals[g] -= a[i]
			counts[g]--
		}
	}
	search(0)
	fmt.Println(answer)
}
